-- SRS-AUD-02 / CLAUDE.md §2: result_events is append-only. Reject UPDATE and DELETE for every role,
-- including the application user, so no code path (or manual SQL) can rewrite audit history.
CREATE FUNCTION reject_result_event_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'result_events is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER result_events_append_only
  BEFORE UPDATE OR DELETE ON "result_events"
  FOR EACH ROW EXECUTE FUNCTION reject_result_event_mutation();

-- TRUNCATE bypasses row triggers, so block it with a statement-level trigger.
CREATE TRIGGER result_events_no_truncate
  BEFORE TRUNCATE ON "result_events"
  FOR EACH STATEMENT EXECUTE FUNCTION reject_result_event_mutation();
